import{_ as t,o as a,c as i,a2 as r}from"./chunks/framework.CD2m2Tvf.js";const p=JSON.parse('{"title":"Say It Out Loud: Consolidated Spoken Interview Scripts","description":"","frontmatter":{},"headers":[],"relativePath":"14-say-it-out-loud.md","filePath":"14-say-it-out-loud.md"}'),n={name:"14-say-it-out-loud.md"};function o(s,e,l,c,d,u){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="say-it-out-loud-consolidated-spoken-interview-scripts" tabindex="-1">Say It Out Loud: Consolidated Spoken Interview Scripts <a class="header-anchor" href="#say-it-out-loud-consolidated-spoken-interview-scripts" aria-label="Permalink to &quot;Say It Out Loud: Consolidated Spoken Interview Scripts&quot;">​</a></h1><p>This page aggregates all first-person spoken interview scripts for <strong>14-Tracing-Backend</strong>. Rehearse each aloud without notes.</p><hr><h2 id="feature-1-opentelemetry-otlp-ingestion-collector" tabindex="-1">Feature 1: OpenTelemetry OTLP Ingestion Collector <a class="header-anchor" href="#feature-1-opentelemetry-otlp-ingestion-collector" aria-label="Permalink to &quot;Feature 1: OpenTelemetry OTLP Ingestion Collector&quot;">​</a></h2><blockquote><p>&quot;I built the OpenTelemetry ingestion collector using FastAPI and an asynchronous queue buffer. When microservices emit telemetry, they POST span batches to our OTLP endpoint. Rather than performing synchronous database writes on the request thread, I validate the payload schema, scrub sensitive header and tag attributes using our regex PII filter, and push the batch into a bounded in-memory ring buffer. Background workers drain this buffer using batch inserts into ClickHouse. If downstream storage slows down, the collector applies backpressure and returns a 429 status code with a Retry-After header, preventing out-of-memory crashes.&quot;</p></blockquote><hr><h2 id="feature-2-tail-based-intelligent-sampling" tabindex="-1">Feature 2: Tail-Based Intelligent Sampling <a class="header-anchor" href="#feature-2-tail-based-intelligent-sampling" aria-label="Permalink to &quot;Feature 2: Tail-Based Intelligent Sampling&quot;">​</a></h2><blockquote><p>&quot;One of the most impactful systems I implemented is our tail-based sampling engine. If you use standard 1% head-based sampling at the gateway, you end up throwing away 99% of your catastrophic failures and latency anomalies because you don&#39;t know the request failed until it finishes. My tail sampler holds spans in an in-memory sliding window for 30 seconds. When the root span closes, the engine inspects the entire trace tree: if any child span recorded an unhandled exception or breached our p99 latency threshold, the trace is promoted for permanent storage. Otherwise, it is probabilistically downsampled. This cut storage footprint by over 75% while maintaining 100% visibility into incident regressions.&quot;</p></blockquote><hr><h2 id="feature-3-span-directed-acyclic-graph-critical-path" tabindex="-1">Feature 3: Span Directed Acyclic Graph &amp; Critical Path <a class="header-anchor" href="#feature-3-span-directed-acyclic-graph-critical-path" aria-label="Permalink to &quot;Feature 3: Span Directed Acyclic Graph &amp; Critical Path&quot;">​</a></h2><blockquote><p>&quot;To help developers pinpoint why a trace took two seconds, I wrote the critical path graph traversal engine. When a trace is opened in the UI, my backend fetches all associated spans and constructs a Directed Acyclic Graph based on parent-child IDs. It normalizes clock drift between microservices and performs a topological traversal to compute the true critical path—the exact chain of blocking operations that directly dictated the total response time. Parallel spans that completed while waiting for a slower query are filtered out. The critical path spans are returned to our React frontend and illuminated in bright red on the waterfall Gantt chart.&quot;</p></blockquote><hr><h2 id="feature-4-statistical-anomaly-detection-causal-graph" tabindex="-1">Feature 4: Statistical Anomaly Detection &amp; Causal Graph <a class="header-anchor" href="#feature-4-statistical-anomaly-detection-causal-graph" aria-label="Permalink to &quot;Feature 4: Statistical Anomaly Detection &amp; Causal Graph&quot;">​</a></h2><blockquote><p>&quot;I developed an anomaly detection engine that continuously analyzes incoming telemetry without requiring heavy offline model training. It uses moving-window z-score calculations and service dependency graph traversal. When a service&#39;s latency deviates by more than three standard deviations from its rolling hourly baseline, or if a service suddenly introduces a novel downstream RPC call, an anomaly alert is raised. The root cause module traverses the dependency tree backward from the symptom to the origin, successfully distinguishing between victim services that were merely waiting and the culprit service holding the lock.&quot;</p></blockquote><hr><h2 id="feature-5-pre-trained-llm-automated-incident-summarizer" tabindex="-1">Feature 5: Pre-trained LLM Automated Incident Summarizer <a class="header-anchor" href="#feature-5-pre-trained-llm-automated-incident-summarizer" aria-label="Permalink to &quot;Feature 5: Pre-trained LLM Automated Incident Summarizer&quot;">​</a></h2><blockquote><p>&quot;I integrated a pre-trained LLM into our incident triage workflow to turn raw span trees into plain-English incident postmortems. When an engineer clicks &#39;Summarize Incident&#39;, my backend extracts the critical path spans, error messages, and anomaly scores, scrubs any potential secrets or PII, and sends a strictly structured prompt to the model API. The LLM returns a parsed JSON payload explaining what failed, which downstream resource was bottlenecked, and suggested fixes—like adding a database index or tuning a connection pool. I used zero custom ML model training; everything is grounded in exact telemetry data to prevent hallucinations.&quot;</p></blockquote><hr><h2 id="rehearsal-checklist" tabindex="-1">Rehearsal Checklist <a class="header-anchor" href="#rehearsal-checklist" aria-label="Permalink to &quot;Rehearsal Checklist&quot;">​</a></h2><ul><li>[ ] F1: OTLP Ingestion Collector (under 60 seconds)</li><li>[ ] F2: Tail-Based Adaptive Sampling (under 75 seconds)</li><li>[ ] F3: Span DAG &amp; Critical Path Engine (under 60 seconds)</li><li>[ ] F4: Statistical Anomaly Detection (under 60 seconds)</li><li>[ ] F5: Pre-trained LLM Incident Summarizer (under 60 seconds)</li></ul>',20)])])}const m=t(n,[["render",o]]);export{p as __pageData,m as default};
